#!/usr/bin/env bash
# Remove all compiled/generated artifacts. Keeps out/.
set -euo pipefail
cd "$(dirname "$0")"
export PATH="$HOME/.cargo/bin:$PATH"
[ -f ~/.cargo/env ] && . ~/.cargo/env

# 1. cargo build cache (target/ entirely)
if command -v cargo >/dev/null 2>&1; then
    cargo clean
else
    # cargo not installed; cargo clean only ever removes target/
    rm -rf target
fi

# 2. wasm-bindgen node glue generated by build.sh (keeps hand-written e2e sources)
rm -f test/node/ftp_engine.js \
      test/node/ftp_engine.d.ts \
      test/node/ftp_engine_bg.wasm \
      test/node/ftp_engine_bg.wasm.d.ts

# 3. e2e harness deps (re-install with bun install to re-run tests)
rm -rf test/node/node_modules

# 4. macOS Finder junk
find . -name '.DS_Store' -type f -prune -exec rm -f {} +

echo "clean done"
